import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

// specs/hal-engine-config-hooks/spec.md#8
it('preserves a string rejection as the onError cause and caller rejection (specs/hal-engine-config-hooks/spec.md#8)', async () => {
  const thrown = 'string boom';
  const calls: string[] = [];
  let hookError: Error | undefined;
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw thrown;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), undefined, {
    hooks: {
      onError: async (_session, error) => {
        calls.push('onError');
        hookError = error;
      },
      afterSession: async () => {
        calls.push('afterSession');
      },
    },
  });

  const rejection = await orchestrator.processMessage(session).then(
    () => 'resolved unexpectedly',
    error => error as unknown
  );

  expect({
    rejection,
    calls,
    isError: hookError instanceof Error,
    message: hookError?.message,
    cause: hookError?.cause,
  }).toEqual({
    rejection: thrown,
    calls: ['onError', 'afterSession'],
    isError: true,
    message: thrown,
    cause: thrown,
  });
});

